// D_PHY_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module D_PHY_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_hs_req,
  input logic  c_esc_req,
  input logic  c_esc_release,
  input logic  c_irq_clear,
  input logic [7:0] c_esc_cmd,
  input logic [7:0] c_hs_tx_data,
  input logic [7:0] c_lpdt_data,
  input logic  c_lpdt_last,
  input logic [7:0] c_rx_data,
  input logic [7:0] c_rx_esc_cmd,
  input logic  c_rx_hs_active,
  input logic  c_rx_ulps,
  input logic  c_hs_tx_valid,
  input logic  c_hs_tx_ready,
  input logic  c_lpdt_valid,
  input logic  c_lpdt_ready,
  input logic  c_rx_data_valid,
  input logic  c_rx_esc_valid,
  input logic  c_hs_tx_done,
  input logic  c_esc_done,
  input logic  c_irq
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 12;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:11];          // model of every stored word
  logic [10:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_HS_TX;          // full / valid pulse / available
  logic m_state_LPDT;          // full / valid pulse / available
  logic m_state_RX;          // full / valid pulse / available
  logic m_state_RX_ESC;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_hs_tx_done) m_set[0] = 1'b1;
    if (c_esc_done) m_set[1] = 1'b1;
    if (c_irq) m_set[2] = 1'b1;
    if (m_state_HS_TX && c_hs_tx_ready) m_set[3] = 1'b1;
    if (m_wr && m_map && (m_idx == 7) && m_state_HS_TX) m_set[4] = 1'b1;
    if (m_state_LPDT && c_lpdt_ready) m_set[5] = 1'b1;
    if (m_wr && m_map && (m_idx == 8) && m_state_LPDT) m_set[6] = 1'b1;
    if (c_rx_data_valid && !m_state_RX) m_set[7] = 1'b1;
    if (c_rx_data_valid && m_state_RX && (m_rd && m_map && m_idx == 9)) m_set[7] = 1'b1;
    if (c_rx_data_valid && m_state_RX && !(m_rd && m_map && m_idx == 9)) m_set[8] = 1'b1;
    if (c_rx_esc_valid && !m_state_RX_ESC) m_set[9] = 1'b1;
    if (c_rx_esc_valid && m_state_RX_ESC && (m_rd && m_map && m_idx == 10)) m_set[9] = 1'b1;
    if (c_rx_esc_valid && m_state_RX_ESC && !(m_rd && m_map && m_idx == 10)) m_set[10] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_HS_TX <= 0;
      m_state_LPDT <= 0;
      m_state_RX <= 0;
      m_state_RX_ESC <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h7FF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 5) ? PWDATA & m_be & 32'hF : 0;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 7 && !m_state_HS_TX) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 7 && !m_state_HS_TX) m_state_HS_TX <= 1;
      if (m_state_HS_TX && c_hs_tx_ready) m_state_HS_TX <= 0;
      if (m_wr && m_map && m_idx == 8 && !m_state_LPDT) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'h1FF;
      if (m_wr && m_map && m_idx == 8 && !m_state_LPDT) m_state_LPDT <= 1;
      if (m_state_LPDT && c_lpdt_ready) m_state_LPDT <= 0;
      if (c_rx_data_valid && (!m_state_RX || (m_rd && m_map && m_idx == 9))) begin
        m_w[9] <= (32'(c_rx_data[7:0]) << 0);
        m_state_RX <= 1;
      end else if ((m_rd && m_map && m_idx == 9)) m_state_RX <= 0;
      if (c_rx_esc_valid && (!m_state_RX_ESC || (m_rd && m_map && m_idx == 10))) begin
        m_w[10] <= (32'(c_rx_esc_cmd[7:0]) << 0);
        m_state_RX_ESC <= 1;
      end else if ((m_rd && m_map && m_idx == 10)) m_state_RX_ESC <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h44500200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RX_ESC, m_state_RX, m_state_LPDT, m_state_HS_TX});
      4: return m_w[4];
      5: return 0;
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return (32'(c_rx_hs_active) << 0) | (32'(c_rx_ulps) << 1);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][10:0] & m_w[2][10:0]))
  `SVA_INV(a_core_hs_req, c_hs_req == m_pulse_CMD[0])
  `SVA_INV(a_core_esc_req, c_esc_req == m_pulse_CMD[1])
  `SVA_INV(a_core_esc_release, c_esc_release == m_pulse_CMD[2])
  `SVA_INV(a_core_irq_clear, c_irq_clear == m_pulse_CMD[3])
  `SVA_INV(a_core_esc_cmd, c_esc_cmd == m_w[6][7:0])
  `SVA_INV(a_core_hs_tx_data, c_hs_tx_data == m_w[7][7:0])
  `SVA_INV(a_core_lpdt_data, c_lpdt_data == m_w[8][7:0])
  `SVA_INV(a_core_lpdt_last, c_lpdt_last == m_w[8][8:8])
  `SVA_INV(a_core_hs_tx_valid, c_hs_tx_valid == m_state_HS_TX)
  `SVA_INV(a_core_lpdt_valid, c_lpdt_valid == m_state_LPDT)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_hs_req == 1'h0 && c_esc_req == 1'h0 && c_esc_release == 1'h0 && c_irq_clear == 1'h0 && c_esc_cmd == 8'h0 && c_hs_tx_data == 8'h0 && c_lpdt_data == 8'h0 && c_lpdt_last == 1'h0 && !c_hs_tx_valid && !c_lpdt_valid)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CMD, m_rd && m_map && m_idx == 5)
  `FC(wr_CMD, m_wr && m_map && m_idx == 5)
  `FC(rd_ESC, m_rd && m_map && m_idx == 6)
  `FC(wr_ESC, m_wr && m_map && m_idx == 6)
  `FC(rd_HS_TX, m_rd && m_map && m_idx == 7)
  `FC(wr_HS_TX, m_wr && m_map && m_idx == 7)
  `FC(rd_LPDT, m_rd && m_map && m_idx == 8)
  `FC(wr_LPDT, m_wr && m_map && m_idx == 8)
  `FC(rd_RX, m_rd && m_map && m_idx == 9)
  `FC(wr_RX, m_wr && m_map && m_idx == 9)
  `FC(rd_RX_ESC, m_rd && m_map && m_idx == 10)
  `FC(wr_RX_ESC, m_wr && m_map && m_idx == 10)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 11)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 11)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_HS_SENT_set, m_set[0])
  `FC(irq_HS_SENT_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_HS_SENT_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_HS_SENT_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_ESC_DONE_set, m_set[1])
  `FC(irq_ESC_DONE_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_ESC_DONE_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_ESC_DONE_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_ERROR_set, m_set[2])
  `FC(irq_ERROR_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_ERROR_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_ERROR_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_HS_TX_DONE_set, m_set[3])
  `FC(irq_HS_TX_DONE_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_HS_TX_DONE_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_HS_TX_DONE_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_HS_TX_OVF_set, m_set[4])
  `FC(irq_HS_TX_OVF_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_HS_TX_OVF_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_HS_TX_OVF_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_LPDT_DONE_set, m_set[5])
  `FC(irq_LPDT_DONE_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_LPDT_DONE_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_LPDT_DONE_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_LPDT_OVF_set, m_set[6])
  `FC(irq_LPDT_OVF_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_LPDT_OVF_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_LPDT_OVF_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(irq_RX_AVAIL_set, m_set[7])
  `FC(irq_RX_AVAIL_cleared, m_w[1][7] && m_wr && m_map && m_idx == 1 && PWDATA[7] && PSTRB[0])
  `FC(irq_RX_AVAIL_masked, m_w[1][7] && !m_w[2][7])
  `FC(irq_RX_AVAIL_drives_pin, m_w[1][7] && m_w[2][7] && irq)
  `FC(irq_RX_OVF_set, m_set[8])
  `FC(irq_RX_OVF_cleared, m_w[1][8] && m_wr && m_map && m_idx == 1 && PWDATA[8] && PSTRB[1])
  `FC(irq_RX_OVF_masked, m_w[1][8] && !m_w[2][8])
  `FC(irq_RX_OVF_drives_pin, m_w[1][8] && m_w[2][8] && irq)
  `FC(irq_RX_ESC_AVAIL_set, m_set[9])
  `FC(irq_RX_ESC_AVAIL_cleared, m_w[1][9] && m_wr && m_map && m_idx == 1 && PWDATA[9] && PSTRB[1])
  `FC(irq_RX_ESC_AVAIL_masked, m_w[1][9] && !m_w[2][9])
  `FC(irq_RX_ESC_AVAIL_drives_pin, m_w[1][9] && m_w[2][9] && irq)
  `FC(irq_RX_ESC_OVF_set, m_set[10])
  `FC(irq_RX_ESC_OVF_cleared, m_w[1][10] && m_wr && m_map && m_idx == 1 && PWDATA[10] && PSTRB[1])
  `FC(irq_RX_ESC_OVF_masked, m_w[1][10] && !m_w[2][10])
  `FC(irq_RX_ESC_OVF_drives_pin, m_w[1][10] && m_w[2][10] && irq)
  `FC(cmd_hs_req, m_pulse_CMD[0])
  `FC(cmd_esc_req, m_pulse_CMD[1])
  `FC(cmd_esc_release, m_pulse_CMD[2])
  `FC(cmd_irq_clear, m_pulse_CMD[3])
  `FC(HS_TX_handshake, m_state_HS_TX && c_hs_tx_ready)
  `FC(HS_TX_backpressure, m_state_HS_TX && !c_hs_tx_ready)
  `FC(HS_TX_write_while_full, m_wr && m_map && m_idx == 7 && m_state_HS_TX)
  `FC(LPDT_handshake, m_state_LPDT && c_lpdt_ready)
  `FC(LPDT_backpressure, m_state_LPDT && !c_lpdt_ready)
  `FC(LPDT_write_while_full, m_wr && m_map && m_idx == 8 && m_state_LPDT)
  `FC(RX_capture, c_rx_data_valid && !m_state_RX)
  `FC(RX_overflow, c_rx_data_valid && m_state_RX && !(m_rd && m_map && m_idx == 9))
  `FC(RX_pop, m_rd && m_map && m_idx == 9 && m_state_RX)
  `FC(RX_read_empty, m_rd && m_map && m_idx == 9 && !m_state_RX)
  `FC(RX_pop_and_capture, c_rx_data_valid && m_state_RX && m_rd && m_map && m_idx == 9)
  `FC(RX_ESC_capture, c_rx_esc_valid && !m_state_RX_ESC)
  `FC(RX_ESC_overflow, c_rx_esc_valid && m_state_RX_ESC && !(m_rd && m_map && m_idx == 10))
  `FC(RX_ESC_pop, m_rd && m_map && m_idx == 10 && m_state_RX_ESC)
  `FC(RX_ESC_read_empty, m_rd && m_map && m_idx == 10 && !m_state_RX_ESC)
  `FC(RX_ESC_pop_and_capture, c_rx_esc_valid && m_state_RX_ESC && m_rd && m_map && m_idx == 10)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind D_PHY_apb D_PHY_apb_sva u_apb_sva (.*);
